    for k, meta in diagrams.items():
        errs = verify_diagram(meta["ascii"], f"ORCH-{k}", kind=meta["kind"])
        if errs:
            raise SystemExit(f"ASCII verification failed for ORCH-{k} ({meta['kind']}): {errs}")
    return diagrams


